pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the sent amount and the caller address
    function testFuzz_property(uint256 fuzzAmount, address caller) public {
        // keep caller as a real EOA-like address and amount within a wide range
        vm.assume(caller != address(0));
        // bound the fuzzAmount to a reasonable ether range up to, say, 100 ether
        uint256 amount = bound(fuzzAmount, 0, 100 ether);

        // fund the caller so they can send the amount
        vm.deal(caller, amount);

        // call fallback from the caller with the fuzzed amount and observe whether it succeeds
        bool ok;
        vm.prank(caller);
        try c.f{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

