pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: an actor address and a starting block timestamp and a block number parity
    // We will fuzz an address and a starting timestamp and a block number; keep wide domain.
    function testFuzz_property(address actor, uint64 startTimestamp, uint64 startBlock) public {
        vm.assume(actor != address(0));

        // Bound the timestamp and block to reasonable values
        uint256 ts = uint256(bound(startTimestamp, 1, type(uint64).max - 2));
        uint256 bn = uint256(bound(startBlock, 1, type(uint64).max - 2));

        // Give actor enough balance to send 10 ether twice
        vm.deal(actor, 20 ether);

        // Set initial chain state
        vm.warp(ts);
        vm.roll(bn);

        // First call: actor sends exactly 10 ether to trigger fallback
        vm.prank(actor);
        c.f{value: 10 ether}();

        // Record pastBlockTime after first call
        uint256 t1 = c.pastBlockTime();

        // Do NOT advance block or timestamp: keep same block
        // Second call: same block and timestamp; in the reference contract this should fail the require(block.timestamp > pastBlockTime)
        vm.prank(actor);
        bool ok;
        try c.f{value: 10 ether}() {
            ok = true; // succeeded
        } catch {
            ok = false; // reverted
        }

        // Single assertion: In the reference contract, the second call in the same block MUST revert, so either the call failed (ok==false) OR, if it succeeded, pastBlockTime must have advanced to current block.timestamp.
        // Because we did not advance time, the reference always has ok == false. The mutant (timestamp check removed) will allow ok == true and pastBlockTime unchanged (equal to t1).
        // We assert that either the second call reverted (ok == false) or, if it did not revert, pastBlockTime > t1.
        uint256 t2 = c.pastBlockTime();
        assertTrue(!ok || t2 > t1);
    }
}

